import{_ as h,C as o,o as d,c as p,j as t,a,E as n,a8 as w}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/wrfbI5eyLAI-640.webp",m="/schedule-dashboard/thumbs/yt/wrfbI5eyLAI-1280.webp",s="/schedule-dashboard/thumbs/yt/Xyb1Bn_L2U4-640.webp",c="/schedule-dashboard/thumbs/yt/Xyb1Bn_L2U4-1280.webp",B=JSON.parse('{"title":"AI Digest · Thu 26 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-26","routine":"digest"},"relativePath":"digest/2026-11-26.md","filePath":"digest/[date].md"}'),u={name:"digest/2026-11-26.md"},g=r+" 640w, "+m+" 1280w",b=s+" 640w, "+c+" 1280w",y={id:"ai-digest-·-thu-26-nov-2026",tabindex:"-1"};function f(v,e,k,_,A,I){const i=o("Badge"),l=o("DayFilter");return d(),p("div",null,[t("h1",y,[e[0]||(e[0]=a("AI Digest · Thu 26 Nov 2026 ",-1)),n(i,{type:"tip",text:"2"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-thu-26-nov-2026","aria-label":'Permalink to "AI Digest · Thu 26 Nov 2026 <Badge type="tip" text="2" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 26 Nov 2026 · run date Thu 26 Nov 2026 · 2 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` There are 2 new talks. The freshest is Lance Martin (Anthropic) on 1,000 Claude agents formalizing Fermat's Last Theorem, plus memory "dreaming" (26 Nov, 1:30 AM IST). The multi-agent result is new, so it's worth watching. Quinn Slack on running Amp with 21 people (25 Nov, 7:30 PM IST) starts on familiar ground but gets concrete about how they operate, so skim it.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" No new uploads in the last 24 hours.")])],-1)),n(l),e[5]||(e[5]=w('<div class="grid cards2"><article class="it full" id="v-wrfbI5eyLAI" data-title="1,000 Claude Agents Formalized Fermat&#39;s Last Theorem — Lance Martin, Anthropic" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=wrfbI5eyLAI" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+g+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=wrfbI5eyLAI" target="_blank" rel="noopener">1,000 Claude Agents Formalized Fermat&#39;s Last Theorem — Lance Martin, Anthropic</a></h3><div class="meta">AI Engineer · Lance Martin, Anthropic · uploaded 26 Nov, 1:30 AM IST · 18:43</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — short, and the 1,000-agent Fermat run is genuinely new; the dreaming half partly repeats the Claude Managed Agents series but adds real numbers.</div><div class="repeat">🔁 Repeat: &#39;multi-agent / A2A&#39; — seen 33 times before. New here: a team of 1,000 Claude agents formalized Fermat&#39;s Last Theorem in Lean with only Git and a SQL database, no domain-specific harness and no human steering on the solution.</div><div class="repeat">🔁 Repeat: &#39;self-improving agents&#39; — seen 28 times before. New here: Anthropic&#39;s own numbers on &quot;dreaming&quot;: a search-only baseline scored 53% on 25 company questions, and a Claude-built wiki beat it as more dreaming compute was added.</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 25 times before. New here: benchmark evidence that stronger models decide by themselves when to write and read memory, and the Pokémon comparison of Sonnet 3.7&#39;s bloated memory folder vs Fable 5&#39;s tight one.</div><div class="sh">1,000 agents on Fermat&#39;s Last Theorem</div><ul><li><strong>The starting point:</strong> Andrew Wiles&#39;s 1990s proof took seven years, and formalizing it means checking every step by computer in Lean. In September Anthropic did it with about a dozen agents, but only with a domain-specific proof-orchestration harness and a lot of help from a researcher (<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=160s" target="_blank" rel="noopener">2:40</a>)</li><li><strong>The new test:</strong> Go from a dozen to 1,000 agents with no domain harness and no human steering. Each agent has its own sandbox with restricted network access and can reach only Git and a SQL database. Every tool call is watched in real time for things like escapes, plus offline review of all runs every 10 minutes. The prompt just names one lead and 999 helpers (<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=147s" target="_blank" rel="noopener">2:27</a>–<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=237s" target="_blank" rel="noopener">3:57</a>)</li><li><strong>The lead built its own coordination tables:</strong> About 5 minutes in, without being told, the lead created database tables to announce things, assign workers to parts of the theorem, share notes and mark finished Lean code as landed. Agents used these tables to coordinate the whole run (<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=237s" target="_blank" rel="noopener">3:57</a>–<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=320s" target="_blank" rel="noopener">5:20</a>)</li><li><strong>30 hours, self-organizing:</strong> The run took about 30 hours. For hard parts, like one major lemma, the agents built their own task trees and kept reassigning themselves as the proof&#39;s 60 statements were solved. One closing note read &quot;total freeze… magnificent work all 999 of you&quot;. His takeaway: agents can now coordinate long, hard tasks with very simple primitives (<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=310s" target="_blank" rel="noopener">5:10</a>–<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=437s" target="_blank" rel="noopener">7:17</a>)</li></ul><div class="sh">Memory and &quot;dreaming&quot;</div><ul><li><strong>The paradox:</strong> Quoting Kierkegaard (&quot;life can only be understood backwards, but it must be lived forwards&quot;), he says agents write memory greedily during a task, but memory has to be a coherent, non-redundant map. Like human sleep, a separate &quot;dreaming&quot; step should turn daily notes into long-term knowledge (<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=440s" target="_blank" rel="noopener">7:20</a>–<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li><li><strong>Stronger models use memory better:</strong> On the open-source CL Bench (40 database questions, a fresh session each time, with a memory folder and no memory prompting), Sonnet 4.6 barely benefits from memory because it doesn&#39;t reliably write or read it. Newer Sonnet and Opus models get steadily better and write more verified, predictive notes (<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=645s" target="_blank" rel="noopener">10:45</a>)</li><li><strong>Pokémon example:</strong> Sonnet 3.7 filled a huge, indiscriminate memory folder and did worse in the game. Fable 5 kept a much smaller folder of strategic insights and got much further (<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=645s" target="_blank" rel="noopener">10:45</a>–<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=760s" target="_blank" rel="noopener">12:40</a>)</li><li><strong>What dreaming does:</strong> It reflects over transcripts and notes to fix them, build wikis and promote key facts into context loaded at the start of every session. In Pokémon, a wrongly saved landmark location kept sending Claude down a trapdoor in a loop; without dreaming it stayed stuck, and with dreaming it fixed the note and moved on (<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=760s" target="_blank" rel="noopener">12:40</a>–<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=920s" target="_blank" rel="noopener">15:20</a>) (repeat)</li><li><strong>Company wiki test:</strong> Using an anonymized corpus from Stainless (acquired in May), 25 questions answerable only from its documents: plain search scored 53%. A Claude-built wiki kept improving as dreaming tokens were added, and wiki plus search beat search alone. Dreaming also filled placeholder pages and added an index to an incomplete wiki (<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=920s" target="_blank" rel="noopener">15:20</a>–<a href="https://www.youtube.com/watch?v=wrfbI5eyLAI&amp;t=1100s" target="_blank" rel="noopener">18:20</a>)</li></ul></div></article><article class="it full" id="v-Xyb1Bn_L2U4" data-title="How 21 People Built a $100M+ Agent Company — Quinn Slack, Amp" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4" target="_blank" rel="noopener"><img src="'+s+'" srcset="'+b+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4" target="_blank" rel="noopener">How 21 People Built a $100M+ Agent Company — Quinn Slack, Amp</a></h3><div class="meta">AI Engineer · Quinn Slack, CEO of Amp (spun out of Sourcegraph) · uploaded 25 Nov, 7:30 PM IST · 18:01</div><div class="verdict v-skim"><b>Verdict:</b> skim from 7:01 — the opening is familiar &quot;agents change everything&quot; ground, but the operating practices (bug loop, tiny pushes, own CRM, $100M ARR with 21 people) are concrete.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 96 times before. New here: how a 21-person company with no task tracker, no PMs and one meeting a week runs entirely inside its agent and says it makes more than $100M ARR.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 46 times before. New here: agents asked to prove their work in ways no human would, such as comparing every UI frame to remove jitter.</div><div class="repeat">🔁 Repeat: &#39;software cloning&#39; — seen 5 times before. New here: Amp built its own CRM instead of Salesforce, arguing that you only use about 2% of Salesforce anyway.</div><div class="sh">Why they spun out</div><ul><li><strong>The trigger:</strong> In January 2025, before Claude Code, his first simple agent ran commands and checked its own work, and he felt everything about building and selling software would change. Even as CEO of the 200-person Sourcegraph he couldn&#39;t easily change its processes, so about 20 people formed a separate Amp team (<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=150s" target="_blank" rel="noopener">2:30</a>)</li><li><strong>Enterprise-ready is dead:</strong> He argues that working through enterprise checklists to please the average buyer makes a product obsolete within about 3 months. Features like Amp&#39;s cloud agents (&quot;orbs&quot;) and multiplayer can be copied by any competitor, so there&#39;s no lasting feature advantage (<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=150s" target="_blank" rel="noopener">2:30</a>–<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=275s" target="_blank" rel="noopener">4:35</a>)</li><li><strong>Stuck at 21:</strong> During the legal spin-off they couldn&#39;t hire or grant options for a year, until &quot;last Friday&quot;, while competitors grew. That forced a new way of working, and every employee has a big stake in the company (<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=280s" target="_blank" rel="noopener">4:40</a>–<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=400s" target="_blank" rel="noopener">6:40</a>)</li></ul><div class="sh">How Amp works day to day</div><ul><li><strong>Everything in the agent:</strong> No Jira, no task tracking, no support system. Work and even team communication happen in Amp threads, and teammates can join a thread when someone is stuck (<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=400s" target="_blank" rel="noopener">6:40</a>–<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=445s" target="_blank" rel="noopener">7:25</a>)</li><li><strong>Tiny, monitored pushes:</strong> Instead of big releases, push small changes (add logging first), let the agent watch production for an hour before the next push, or run a shadow system next to the old one to check results match (<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=445s" target="_blank" rel="noopener">7:25</a>–<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=515s" target="_blank" rel="noopener">8:35</a>)</li><li><strong>Agents that prove their work:</strong> To remove UI jitter he had the agent compare every frame. Have it make many versions at once (like nine styles of the dictation waveform) instead of asking for one small change at a time (<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=515s" target="_blank" rel="noopener">8:35</a>–<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=575s" target="_blank" rel="noopener">9:35</a>)</li><li><strong>Bug report loop:</strong> When a bug is reported, the agent fixes it, the user gets an apology email and free credits, and the logs are searched for everyone else who hit the same error (for example 17 other people) so they hear about the fix too. He says Amp is basically 100% AI-built and still seen as high quality. He also pushes dictating to your agent (<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=575s" target="_blank" rel="noopener">9:35</a>–<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=715s" target="_blank" rel="noopener">11:55</a>)</li></ul><div class="sh">A different kind of company</div><ul><li><strong>Own CRM instead of Salesforce:</strong> You use about 2% of Salesforce&#39;s features, and an agent can build that plus the integrations you need. He sees SaaS&#39;s &quot;100k salesperson, 10-year deal&quot; model breaking down (<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=715s" target="_blank" rel="noopener">11:55</a>–<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=880s" target="_blank" rel="noopener">14:40</a>)</li><li><strong>No PMs, one meeting a week:</strong> Everyone talks to customers. A sales rep two years out of college built ACH wire payments. Beyond the weekly meeting the rule is &quot;follow your energy&quot;. He says Amp is profitable at more than $100M ARR and 40–50× more efficient than traditional companies, and his advice is &quot;get out of the cage&quot; (<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=880s" target="_blank" rel="noopener">14:40</a>–<a href="https://www.youtube.com/watch?v=Xyb1Bn_L2U4&amp;t=1081s" target="_blank" rel="noopener">18:01</a>)</li></ul></div></article></div>',1))])}const S=h(u,[["render",f]]);export{B as __pageData,S as default};
